function getRosterIds(side){const entries=Object.values(GODS);const byKind=kind=>entries.filter(c=>kind==='god'?(!c.kind||c.kind==='god'):c.kind===kind).map(c=>c.id);const mode=state.rosterMode;if(mode==='mythic-duel'){const duel={olympus:['zeus','poseidon'],ragnarok:['thor','jormungandr'],throne:['horus','seth'],waters:['indra','vritra'],'boss-jormungandr':['thor','jormungandr'],'boss-typhon':['zeus','typhon']}[state.mythicMode]||['zeus','poseidon'];return [duel[side==='p1'?0:1]];}if(mode==='heroes')return byKind('hero');if(mode==='heroes-vs-gods')return side==='p1'?byKind('hero'):byKind('god');if(mode==='titans')return byKind('titan');if(mode==='monsters')return byKind('monster');if(mode==='titans-vs-monsters')return side==='p1'?byKind('titan'):byKind('monster');return byKind('god');}
