function rosterDescription(mode){return ({'mythic-duel':'Los contendientes están fijados por la crónica mitológica.',gods:'Ambos jugadores eligen dioses.',heroes:'Ambos jugadores eligen héroes.', 'heroes-vs-gods':'Jugador 1 elige un héroe y Jugador 2 un dios.',titans:'Ambos jugadores eligen titanes.',monsters:'Ambos jugadores eligen monstruos.','titans-vs-monsters':'Jugador 1 elige un titán y Jugador 2 un monstruo.'})[mode]||'Elige los personajes para el duelo.';}
