function applyMythicMode(mode){const valid=['olympus','ragnarok','throne','waters','boss-jormungandr','boss-typhon'];const next=valid.includes(mode)?mode:'classic';if(next!=='classic'&&state.mythicMode==='classic'){state.selectionBeforeMythic={...state.selected};state.rosterBeforeMythic=state.rosterMode;}if(next==='classic'&&state.mythicMode!=='classic'&&state.selectionBeforeMythic){state.selected={...state.selectionBeforeMythic};state.rosterMode=state.rosterBeforeMythic||'gods';state.selectionBeforeMythic=null;state.rosterBeforeMythic=null;}state.mythicMode=next;if(next!=='classic'){const duel={olympus:['zeus','poseidon'],ragnarok:['thor','jormungandr'],throne:['horus','seth'],waters:['indra','vritra'],'boss-jormungandr':['thor','jormungandr'],'boss-typhon':['zeus','typhon']}[next];state.selected.p1=duel[0];state.selected.p2=duel[1];state.rosterMode='mythic-duel';}const roster=document.getElementById('roster-mode-select');if(roster)roster.value=state.rosterMode;const cfg=document.getElementById('roster-mode-config');if(cfg)cfg.value=state.rosterMode;updateMythicModeUI();renderSelection();buildArenaCache();}
