function updateMutationStatus(){const status=getMutationStatus(),box=document.getElementById('mutation-status');if(!box)return;box.classList.toggle('hidden',!status.active);const label=document.getElementById('mutation-charge-label'),bar=document.getElementById('mutation-charge-bar'),track=box.querySelector('.mutation-charge-track'),stateLabel=document.getElementById('mutation-charge-state');if(label)label.textContent=`${Math.round(status.charge)}%`;if(bar)bar.style.width=`${Math.max(0,Math.min(100,status.charge))}%`;if(track)track.setAttribute('aria-valuenow',String(Math.round(status.charge)));if(stateLabel)stateLabel.textContent=status.ready?'CARGA COMPLETA · EN ESPERA DE EFECTOS':status.stage>=75?'FASE III · CONTROLES INVERTIDOS':status.stage>=50?'FASE II · DIVISIÓN CELULAR HABILITADA':status.stage>=25?'FASE I · RIVAL RALENTIZADO':'CARGA EN ACUMULACIÓN';}
