function loop(now){if(state.finished||(!state.running&&!state.paused)){draw();return;}const dt=Math.min(.033,(now-(state.lastFrame||now))/1000||0);state.lastFrame=now;if(state.running&&!state.paused){if(countdown>0){countdown-=dt;if(countdown<=0){document.getElementById('arena-overlay').classList.add('hidden');}else{const value=Math.ceil(countdown);document.getElementById('arena-overlay').querySelector('strong').textContent=String(value);}}else{updatePaddles(dt);if(state.mode==='cpu'&&state.skillsEnabled&&state.ball.vx>0&&state.paddles.p2.cooldown<=0&&Math.random()<dt*.16)activateAbility('p2');updatePhysics(dt);updateEffects(dt);}}draw();if(now-lastHud>100){updateHUD();lastHud=now;}state.raf=requestAnimationFrame(loop);}
